'use strict';
PAGES.splice(PAGES.findIndex(p=>p[0]==='ranking'),0,['scene5','◈','Клубы и регионы']);
let sceneRegion5='ALL';
clubAvatar12=function(t,small=false){
 if(t.fiction)return '<span class="club-avatar12'+(small?' small-avatar12':'')+'"><b>'+esc(t.short||t.name.slice(0,3))+'</b></span>';
 const src=t.logo5||([0,5,8,11].includes(t.id)?'assets/club-logos/v5/core-'+t.id+'.webp':'assets/club-logos/'+t.id+'.webp');
 return '<span class="club-avatar12'+(small?' small-avatar12':'')+'"><img src="'+esc(src)+'" width="64" height="64" alt="Логотип '+esc(t.name)+'" loading="lazy"><b hidden>'+esc(t.short||t.name.slice(0,3))+'</b></span>';
};
const UI5={
 rule(e){const q=e.qualification,r=q.policy;return '<section class="panel v5-rules"><span class="eyebrow">V5.0 / '+esc(r.label)+'</span><h2>'+r.direct+' прямых приглашений · '+(r.field-r.direct)+' мест отбора</h2><div class="v5-quotas">'+Object.entries(r.quotas).map(([group,n])=>'<div><strong>'+n+'</strong><span>'+esc(Admissions5.groupName(group))+'</span></div>').join('')+(Object.keys(r.quotas).length?'':'<p>Квалификации не проводятся.</p>')+'</div><p>'+esc(r.note)+'</p><p class="sub">Прямые инвайты: рейтинг сезона (очки → Elo → ID), с резервом опубликованных региональных квот. EPT и выбор организатора заменены игровым рейтингом. Число команд закрытого отбора зависит от реального пула; нет искусственного заполнения сетки. Отбор BO3 круговой — игровая адаптация.</p><a href="'+esc(r.source)+'" target="_blank" rel="noopener">Источник правил допуска ↗</a></section>';},
 scene(){
  const regions=QUALIFIERS.regions,teams=S.teams.filter(t=>sceneRegion5==='ALL'||Qualifiers.region(t)===sceneRegion5);
  return head('V5.0 / РЕАЛЬНАЯ СЦЕНА','Клубы и регионы',S.teams.length+' клубов · 37 согласованных команд T2, включая уже существовавшие Xipto и PlayTime')+'<div class="v5-region-tabs">'+['ALL',...regions].map(r=>btn(r==='ALL'?'Все регионы':r==='EU'?'WEU':r,"sceneRegion5='"+r+"';render()",sceneRegion5===r)).join('')+'</div><section class="panel"><p>Составы — датированные срезы открытых источников. OVR новых игроков задан для баланса игры. Это не прямая трансляция текущих регистраций. Стартовые замены при пересечении срезов отмечены в карточках; дальнейшие трансферы принадлежат карьере.</p><p>'+regions.map(r=>(r==='EU'?'WEU':r)+': '+S.teams.filter(t=>Qualifiers.region(t)===r).length).join(' · ')+'</p></section><div class="v5-clubs">'+teams.map(t=>{
   const d=CLUBS5.find(d=>d.key===t.v5Key),changes=S.v5.replacements.filter(r=>r.team===t.id);
   return '<article class="panel v5-club"><div class="section-head">'+clubAvatar12(t)+'<span class="tag">'+esc(Qualifiers.region(t)==='EU'?'WEU':Qualifiers.region(t))+' · T'+t.tier+'</span></div><h2>'+esc(t.name)+'</h2><p>OVR '+avg(roster(t).map(p=>p.skill)).toFixed(1)+'</p><div class="v5-five">'+roster(t).sort((a,b)=>a.role-b.role).map(p=>'<div><small>POS '+(p.role+1)+'</small><b>'+esc(p.name)+'</b><span>'+Math.round(p.skill)+'</span></div>').join('')+'</div>'+(d?'<p class="sub">Срез '+esc(d.rosterDate)+(d.region==='NA'?' · исторический стак TI-квалификаций; текущая активность не подтверждена':'')+'</p><a href="'+esc(d.source)+'" target="_blank" rel="noopener">Источник состава ↗</a>'+(d.logoKind==='game-monogram'?'<p class="sub">Игровая монограмма: опубликованный логотип не найден.</p>':''):'<p class="sub">Клуб основной базы игры; сохранён состав карьеры.</p>')+changes.map(r=>'<p class="v5-note">В источнике: '+esc(r.listed)+'. Игровая замена: '+esc(S.players[r.player].name)+' — исходные срезы пересекаются по одному игроку.</p>').join('')+'</article>';
  }).join('')+'</div>'+(S.v5.legacyArchive.clubs.length?'<section class="panel"><h2>Архив прежней сцены</h2><p>Убрано вымышленных клубов: '+S.v5.legacyArchive.clubs.length+'. Архивировано событий: '+S.v5.legacyArchive.events.length+'. Имена и результаты доступны в экспорте карьеры, v5.legacyArchive. История не переименована в результаты реальных клубов.</p></section>':'');
 }
};
const qualifiersUI5=qualifiersView;
qualifiersView=function(){
 const e=qualifierParent();if(e?.qualification?.majorVersion!==5)return qualifiersUI5();
 const q=e.qualification,parents=qualifierParents(),children=S.events.filter(c=>c.qualifierFor===e.id);
 return head('V5.0 / ПУТЬ НА ТУРНИР','Квалификации','Опубликованные схемы допуска и результаты вашей карьеры.')+'<div class="qualifier-controls"><select aria-label="Основной турнир" onchange="selectedQualifierEvent=+this.value;render()">'+parents.map(p=>'<option value="'+p.id+'" '+(p.id===e.id?'selected':'')+'>'+esc(p.name)+'</option>').join('')+'</select></div>'+UI5.rule(e)+qualifierCard(e)+'<div class="qualifier-invites">'+(q.invited||[]).map(r=>'<article class="panel">'+clubAvatar12(S.teams[r.team])+'<h3>'+esc(S.teams[r.team].name)+'</h3><p>'+esc(r.text)+'</p></article>').join('')+'</div><div class="qualifier-regions">'+children.map(c=>'<article class="panel"><span class="eyebrow">'+esc(Admissions5.groupName(c.qualifierRegion))+'</span><h2>'+c.quota+' мест · '+c.entrants.length+' клубов</h2><p>'+date(c.day)+' · '+(c.walkover5?'Проход без матчей: число участников равно квоте':c.done?'Отбор завершён':'Круговой отбор BO3')+'</p>'+(c.done?'<p>Прошли: '+c.inviteWinners.map(id=>esc(S.teams[id].name)).join(', ')+'</p>':'')+btn('Таблица и матчи →','showBracket('+c.id+')')+'</article>').join('')+'</div>'+(q.status==='pending'?'<section class="panel"><p>Список приглашений фиксируется за '+QUALIFIERS.snapshotLead+' дней до турнира.</p></section>':'');
};
const card5=qualifierCard;
qualifierCard=function(e,...args){const html=card5(e,...args);return e.qualification?.majorVersion===5?html.replace(/Ваш индекс [0-9.]+\./,'Место в снимке рейтинга: '+(e.qualification.rows?.find(r=>r.team===S.club)?.rank??'—')+'.'):html;};
const render5=render;
render=function(...args){const r=render5(...args);if(S?.v5?.sceneReady){$('broadcastStatus33c').innerHTML=$('broadcastStatus33c').innerHTML.replace(/V4\.0 [AB] \/ ARENA/,'V5.0 / ARENA');if(page==='scene5')$('app').innerHTML=UI5.scene();}else if(S?.v5?.pending)$('app').innerHTML='<div class="notice">V5.0: реальная сцена будет подключена после завершения текущего турнира или КВ. Активные матчи сохраняют участников.</div>'+$('app').innerHTML;return r;};
const settings5=settings;
settings=function(){return settings5().replace('Текущая версия 4.0','Текущая версия 5.0').replace('Выбери любой из 16 клубов','Выбери любой из '+S.teams.length+' клубов').replace('У всех стартовый бюджет $1,5 млн.','Стартовый бюджет зависит от клуба.').replace('Шестнадцать клубов включены в игровую лигу','Все клубы справочника включены в игровую лигу').replace('Стартовые OVR реальных игроков рассчитаны по OpenDota.','OVR основной базы основан на OpenDota; для добавленных игроков V5 заданы игровые оценки.');};
const ranking5=rankingView13;
rankingView13=function(){return ranking5().replace(/V4\.0: новые крупные турниры[\s\S]*?сохраняют составы\./,'V5.0: число прямых инвайтов и региональных мест задано регламентом организатора. Полная схема и источники — в квалификациях.');};
